@js:
var result = [];
var push = function(title, url, size) {
    result.push({
        title: title,
        url: url,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: size
        }
    });
};
var regions = [
    {name: '全部', code: '26'},
    {name: '韩漫', code: 'Kc'},
    {name: '日漫', code: 'Jc'},
    {name: '中漫', code: 'Cc'},
    {name: '欧美漫', code: 'Ec'},
    {name: '其他', code: 'Oc'}
];
var types = [
    'All', '恋爱', '冒险', '生活', '校园', '热血', '魔法', '悬疑', '科幻',
    '运动', '都市', '耽美', '搞笑', '单女主', '纯爱', '总裁', '奇幻', '恐怖',
    '灵异', '异能', '穿越', '剧情', '古风', '言情', '玄幻', '复仇', '多女主',
    '霸总', '虐恋', '青春', '真人', '重生', '甜宠', '游戏竞技', '家庭', 'BL',
    '民国', '同人', '系统', '爱情', '美人', '喜剧', '纯真', '腹黑', '财阀',
    '后宫', '战争', '修真', '其他'
];
for (var r = 0; r < regions.length; r++) {
    var region = regions[r];
    for (var t = 0; t < types.length; t++) {
        var type = types[t];
        var isAll = (t === 0);
        var base;
        if (isAll) {
            base = '/type/' + region.code;
        } else {
            var encodedType = (type === 'All' || type === 'BL') ? type : encodeURIComponent(type);
            base = '/type/' + region.code + '--' + encodedType;
        }
        var url;
        if (isAll) {
            url = '@js:var base="' + base + '";if(page==1){base+"-----.html";}else{base+"---"+page+"--.html";}';
        } else {
            url = '@js:var base="' + base + '";if(page==1){base+"---.html";}else{base+"-"+page+"--.html";}';
        }
        var title;
        if (isAll) {
            title = '📌 ' + region.name + '·全部';
        } else {
            title = region.name + '·' + type;
        }
        var size = isAll ? 1 : 0.35;
        push(title, url, size);
    }
}
JSON.stringify(result);

